set-variable.value:
@{
            var jwt = (Jwt)context.Variables["jwt"];
            string oid = jwt.Claims.GetValueOrDefault("oid",  string.Empty);
            return oid.ToLowerInvariant();
        }

@{
            var jwt = (Jwt)context.Variables["jwt"];
            return jwt.Claims.GetValueOrDefault("azp",
                   jwt.Claims.GetValueOrDefault("appid",
                   context.Subscription?.Id ?? "unknown"));
        }

@{
    var jwt = (Jwt)context.Variables["jwt"];
    // v1 tokens: unique_name / upn; v2 tokens: preferred_username
    return jwt.Claims.GetValueOrDefault("preferred_username",
           jwt.Claims.GetValueOrDefault("upn",
           jwt.Claims.GetValueOrDefault("unique_name",
           jwt.Claims.GetValueOrDefault("email", "")))).ToLowerInvariant();
}

@{
    try {
        var body = context.Request.Body.As<string>(preserveContent: true);
        JObject.Parse(body);
        return body;
    } catch { return ""; }
}

@{
            var routeDeployment = context.Request.MatchedParameters.GetValueOrDefault("deployment-id", "");
            if (!string.IsNullOrEmpty(routeDeployment)) {
                return routeDeployment;
            }
            try {
                var body = JObject.Parse((string)context.Variables["requestBody"]);
                return (string)body["model"] ?? "unknown";
            } catch {
                return "unknown";
            }
        }

send-request.set-body:
@{
                return new JObject(
                    new JProperty("operationId", context.RequestId.ToString()),
                    new JProperty("callerKey", (string)context.Variables["callerKey"]),
                    new JProperty("appId", (string)context.Variables["appId"]),
                    new JProperty("deployment", (string)context.Variables["deploymentName"]),
                    new JProperty("period", "Monthly"),
                    new JProperty("currency", "USD"),
                    new JProperty("request", JObject.Parse((string)context.Variables["requestBody"]))
                ).ToString();
            }

when.condition:
@{
                var r = context.Variables.GetValueOrDefault<IResponse>("costReservationResponse");
                return r == null || r.StatusCode != 200;
            }

@{
                var r = context.Variables.GetValueOrDefault<IResponse>("costReservationResponse");
                try {
                    var b = r.Body.As<JObject>(preserveContent: true);
                    return (bool?)b["allowed"] != true || string.IsNullOrEmpty((string)b["reservationId"]);
                } catch { return true; }
            }

set-variable.value:
@{
    try {
        var b = context.Response?.Body?.As<JObject>(preserveContent: true);
        return ((int?)b?["usage"]?["prompt_tokens"]
             ?? (int?)b?["usage"]?["input_tokens"]
             ?? 0);
    } catch { return 0; }
}

@{
    try {
    var b = context.Response?.Body?.As<JObject>(preserveContent: true);
        return ((int?)b?["usage"]?["completion_tokens"]
             ?? (int?)b?["usage"]?["output_tokens"]
             ?? 0);
    } catch { return 0; }
}

@{
    try {
    var b = context.Response?.Body?.As<JObject>(preserveContent: true);
        return ((int?)b?["usage"]?["total_tokens"] ?? 0);
    } catch { return 0; }
}

@{
    try {
    var b = context.Response?.Body?.As<JObject>(preserveContent: true);
        return ((int?)b?["usage"]?["cache_creation_input_tokens"]
             ?? (int?)b?["usage"]?["cache_write_input_tokens"]
             ?? (int?)b?["usage"]?["prompt_tokens_details"]?["cache_write_tokens"]
             ?? (int?)b?["usage"]?["input_tokens_details"]?["cache_write_tokens"]
             ?? 0);
    } catch { return 0; }
}

@{
    try {
    var b = context.Response?.Body?.As<JObject>(preserveContent: true);
        return ((int?)b?["usage"]?["cache_read_input_tokens"]
             ?? (int?)b?["usage"]?["prompt_tokens_details"]?["cached_tokens"]
             ?? (int?)b?["usage"]?["input_tokens_details"]?["cached_tokens"]
             ?? 0);
    } catch { return 0; }
}

@{
    try {
        var b = context.Response?.Body?.As<JObject>(preserveContent: true);
        var usage = b?["usage"];
        var rawInput = ((int?)usage?["prompt_tokens"] ?? (int?)usage?["input_tokens"] ?? 0);
        if (usage?["cache_creation_input_tokens"] != null || usage?["cache_read_input_tokens"] != null) {
            return rawInput;
        }
        var cacheWrite = (int)context.Variables["cacheWriteTokens"];
        var cacheRead = (int)context.Variables["cacheReadTokens"];
        return Math.Max(0, rawInput - cacheWrite - cacheRead);
    } catch { return 0; }
}

@{
    try {
    var b = context.Response?.Body?.As<JObject>(preserveContent: true);
        return (string)b?["model"]
            ?? (string)context.Variables["deploymentName"];
    } catch {
        return (string)context.Variables["deploymentName"];
    }
}

send-request.set-body:
@{
                return new JObject(
                    new JProperty("operationId", context.RequestId.ToString()),
                    new JProperty("deployment", (string)context.Variables["deploymentName"]),
                    new JProperty("model", (string)context.Variables["modelName"]),
                    new JProperty("inputTokens", (int)context.Variables["inputTokens"]),
                    new JProperty("cacheWriteTokens", (int)context.Variables["cacheWriteTokens"]),
                    new JProperty("cacheReadTokens", (int)context.Variables["cacheReadTokens"]),
                    new JProperty("outputTokens", (int)context.Variables["completionTokens"]),
                    new JProperty("status", context.Response.StatusCode)
                ).ToString();
            }

return-response.set-body:
@{
                        return new JObject(
                            new JProperty("error", "rate_limit_or_quota_exceeded"),
                            new JProperty("source", context.LastError.Source),
                            new JProperty("userId", context.Variables.GetValueOrDefault("userId","")),
                            new JProperty("appId",  context.Variables.GetValueOrDefault("appId",""))
                        ).ToString();
                    }
